children.text:
test_interpolation({
  property: 'column-count',
  from: neutralKeyframe,
  to: '20',
}, [
  {at: -0.5, expect: '5'},
  {at: 0, expect: '10'},
  {at: 0.3, expect: '13'},
  {at: 0.7, expect: '17'},
  {at: 1, expect: '20'},
  {at: 1.5, expect: '25'},
]);

test_no_interpolation({
  property: 'column-count',
  from: 'auto',
  to: '20',
});

test_interpolation({
  property: 'column-count',
  from: 'inherit',
  to: '20',
}, [
  {at: -0.5, expect: '35'},
  {at: 0, expect: '30'},
  {at: 0.3, expect: '27'},
  {at: 0.7, expect: '23'},
  {at: 1, expect: '20'},
  {at: 1.5, expect: '15'},
]);

test_interpolation({
  property: 'column-count',
  from: '10',
  to: '1'
}, [
  {at: -0.5, expect: '15'},
  {at: 0, expect: '10'},
  {at: 0.3, expect: '7'},
  {at: 0.7, expect: '4'},
  // Only positive integers are valid
  {at: 1, expect: '1'},
  {at: 1.5, expect: '1'}
]);

test_no_interpolation({
  property: 'column-count',
  from: 'initial',
  to: '5',
});

test_no_interpolation({
  property: 'column-count',
  from: 'unset',
  to: '5',
});
